mapper.update:
UPDATE emp21_un_leave
   SET emp21_total_days  = #{totalDays}
     , emp21_use_days    = #{useDays}
     , emp21_remain_days = #{remainDays}
 WHERE emp21_un_leave_id = #{unLeaveId}
   AND emp21_company_id  = #{companyId}

mapper.delete:
DELETE FROM emp21_un_leave
 WHERE emp21_company_id = #{companyId}
   AND emp21_un_leave_id IN
#{unLeaveId}
